// Set by main.ts from the Studio's language (the one chosen in Blup), and
// again when it changes in the settings: the texts change in place (a copy
// of the language's, as state), so the screens follow without a reload.
const byLang: Record<string, typeof pt> = { pt, en, es };
export const t: typeof pt = live(structuredClone(byLang[navigator.language.toLowerCase().slice(0, 2)] ?? en));
export function setLanguage(lang: string) {
  fill(t, structuredClone(byLang[lang] ?? en));
  document.documentElement.lang = lang;
  shown.lang = lang;
}
// fill copies from's texts into to, keeping to's groups (a screen that kept
// t.prefs keeps reading the same object, now in the new language).
type Texts = { [k: string]: unknown };
const isTexts = (v: unknown): v is Texts => !!v && typeof v === "object" && !Array.isArray(v);
function fill(to: Texts, from: Texts) {
  for (const [k, v] of Object.entries(from)) {
    const into = to[k];
    if (isTexts(v) && isTexts(into)) fill(into, v);
    else to[k] = v;
  }
}
